export interface VocabularyWord {
  /** UUID, generated by crypto.randomUUID() */
  id: string
  /** The original word or phrase */
  word: string
  /** The translated text */
  translation: string
  /** Page URL where the word was collected */
  contextUrl?: string
  /** Surrounding sentence context */
  contextText?: string
  /** ISO 639-3 source language code */
  sourceLanguage?: string
  /** ISO 639-3 target language code */
  targetLanguage?: string
  /** Memory rating: 1 = hardest, 5 = mastered */
  star: 1 | 2 | 3 | 4 | 5
  /** Timestamp when created (Date.now()) */
  createdAt: number
  /** Timestamp of last review */
  lastReviewedAt?: number
  /** How many times reviewed */
  reviewCount: number
  /** Optional user note */
  note?: string
  /**
   * Where the word came from: `local` = collected in the extension,
   * `eudic` = synced from the Eudic vocabulary book.
   */
  source?: VocabularySource
  /** Phonetic transcription, as the Eudic side spells it (e.g. `/ˈæksən/`) */
  phonetic?: string
}

/** Which vocabulary book a word lives in */
export type VocabularySource = "local" | "eudic"

/**
 * Whether a write also reached the Eudic side.
 *
 * The backend reports it separately: a failed Eudic call never rolls back
 * the local change, so the UI has to say so out loud instead of pretending
 * everything went fine.
 */
export interface EudicSyncStatus {
  ok: boolean
  error?: string
}

/** Result of adding a word */
export interface AddVocabularyWordResult {
  /** The new word's id */
  id: string
  /** Present when the write touched the Eudic side */
  eudicSync?: EudicSyncStatus
}

/** Result of updating or deleting a word */
export interface VocabularyWriteResult {
  /** Present when the write touched the Eudic side */
  eudicSync?: EudicSyncStatus
}

/** Payload for adding a new vocabulary word */
export interface AddVocabularyWordPayload {
  word: string
  translation: string
  contextUrl?: string
  contextText?: string
  sourceLanguage?: string
  targetLanguage?: string
}

/** Payload for updating a vocabulary word */
export interface UpdateVocabularyWordPayload {
  id: string
  updates: Partial<Pick<VocabularyWord, "star" | "translation" | "note">>
}

/** Query options for listing vocabulary words */
export interface VocabularyQuery {
  limit?: number
  offset?: number
  sortBy?: "createdAt" | "star" | "word"
  sortOrder?: "asc" | "desc"
  search?: string
  /** Which book to look in; defaults to every source */
  source?: VocabularySource | "all"
}

/** How many words each source holds, for the source filter */
export interface VocabularySourceCounts {
  all: number
  local: number
  eudic: number
}

/** Response for a flashcard session */
export interface FlashcardSession {
  words: VocabularyWord[]
  total: number
}

/** Structured word definition returned by the dictionary REST API */
export interface WordDefinition {
  headword: string
  phoneticUK?: string
  phoneticUS?: string
  pos: string
  senses: Array<{
    number: string
    /** English gloss, absent for senses the dictionary only defines in Chinese. */
    englishDefinition?: string
    chineseDefinition: string
    examples?: Array<{
      text: string
      chinese: string
    }>
  }>
}
